import { SectionSnapshot, Subscriptions } from "./types";

// Four consecutive simulated runs of the periodic enrollment puller.
// Each run is the *full* snapshot fetched that tick -- every section
// appears in every run, same as a real "fetch the whole dataset" puller.
//
// Section stories, run 0 -> run 3:
//   SEC-A: full -> open -> open -> full            (basic transition, then stays open, then closes)
//   SEC-B: full -> open -> open -> full             (same shape, two subscribers -- dedup coverage)
//   SEC-C: full -> open -> full -> open             (closes and genuinely reopens -- must notify twice)
//   SEC-D: full -> open -> open -> full             (transitions, but has zero subscribers)
//   SEC-E: open -> open -> open -> open             (never full to begin with -- negative control)
export const SNAPSHOTS: SectionSnapshot[][] = [
  // run 0
  [
    { sectionId: "SEC-A", enrolledCount: 30, capacity: 30 },
    { sectionId: "SEC-B", enrolledCount: 25, capacity: 25 },
    { sectionId: "SEC-C", enrolledCount: 40, capacity: 40 },
    { sectionId: "SEC-D", enrolledCount: 10, capacity: 10 },
    { sectionId: "SEC-E", enrolledCount: 5, capacity: 50 },
  ],
  // run 1
  [
    { sectionId: "SEC-A", enrolledCount: 28, capacity: 30 }, // opened
    { sectionId: "SEC-B", enrolledCount: 20, capacity: 25 }, // opened
    { sectionId: "SEC-C", enrolledCount: 35, capacity: 40 }, // opened
    { sectionId: "SEC-D", enrolledCount: 8, capacity: 10 }, // opened, no subscribers
    { sectionId: "SEC-E", enrolledCount: 6, capacity: 50 }, // already open, no transition
  ],
  // run 2
  [
    { sectionId: "SEC-A", enrolledCount: 27, capacity: 30 }, // still open
    { sectionId: "SEC-B", enrolledCount: 22, capacity: 25 }, // still open
    { sectionId: "SEC-C", enrolledCount: 40, capacity: 40 }, // closed again (full)
    { sectionId: "SEC-D", enrolledCount: 9, capacity: 10 }, // still open
    { sectionId: "SEC-E", enrolledCount: 7, capacity: 50 }, // still open
  ],
  // run 3
  [
    { sectionId: "SEC-A", enrolledCount: 30, capacity: 30 }, // closed again (full)
    { sectionId: "SEC-B", enrolledCount: 25, capacity: 25 }, // closed again (full)
    { sectionId: "SEC-C", enrolledCount: 33, capacity: 40 }, // reopened -- genuinely new transition
    { sectionId: "SEC-D", enrolledCount: 10, capacity: 10 }, // closed again (full)
    { sectionId: "SEC-E", enrolledCount: 8, capacity: 50 }, // still open
  ],
];

export const SUBSCRIPTIONS: Subscriptions = {
  "SEC-A": ["alice@berkeley.edu"],
  "SEC-B": ["bob@berkeley.edu", "carol@berkeley.edu"],
  "SEC-C": ["dave@berkeley.edu"],
  // SEC-D intentionally has no subscribers.
  "SEC-E": ["erin@berkeley.edu"],
};
